            var wire = reader.Read(11, paths[at + 1]);
            if (wire > 2000UL) throw new GesWireException(GesWireException.InvalidIndex, paths[at + 1]);
            return wire;
        }

        private static double __Value1(ulong wire) => GesWireRules.QuantizedValue(wire, 0L, 1L, 1d);

        internal readonly bool __Same(in World other, string[] paths, int at)
        {
            if (__Wire0(Tick, paths, at) != __Wire0(other.Tick, paths, at)) return false;
            if (__Wire1(X, paths, at) != __Wire1(other.X, paths, at)) return false;
            return true;
        }

        internal void __Quantize(string[] paths, int at)
        {
            X = __Value1(__Wire1(X, paths, at));
        }

        /// <summary>Gets whether another schema has the same wire values, so that it writes the same bytes.</summary>
        /// <param name="other">The other record.</param>
        /// <returns>Whether the wire values are equal.</returns>
        /// <exception cref="GesWireException">A compared value has no wire value, such as a number outside its range.</exception>
        public readonly bool WireEquals(in World other) => __Same(other, __paths, 0);

        /// <summary>Replaces every quantized value by the value its index decodes to, which a receiver reads.</summary>
        /// <exception cref="GesWireException">A quantized value lies outside its range.</exception>
        public void Quantize() => __Quantize(__paths, 0);

        /// <summary>Writes what differs from a baseline, the full record the receiver holds; <see cref="MaxByteCount"/> bytes always suffice.</summary>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <param name="buffer">The buffer.</param>
        /// <returns>The number of bytes written.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, the keys differ, or the buffer is too small.</exception>
        public readonly int WriteDelta(in World baseline, Span<byte> buffer)
        {
            var writer = new GesBitWriter(buffer);
            __WriteDelta(baseline, ref writer, __paths, 0, true);
            return writer.Finish();
        }

        /// <summary>Counts the bytes that <see cref="WriteDelta"/> writes against a baseline, without writing them.</summary>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <returns>The exact byte count.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, or the keys differ.</exception>
        public readonly int DeltaByteCount(in World baseline)
        {
            var writer = GesBitWriter.Counting();
            __WriteDelta(baseline, ref writer, __paths, 0, true);
            return writer.Finish();
        }

        /// <summary>Writes what differs from a baseline into a new array of its exact size. A count comes first: it sizes the
        /// buffer for the elements that the writer tries and takes back, so that the largest delta is not allocated.</summary>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <returns>The bytes.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, or the keys differ.</exception>
        public readonly byte[] ToDeltaBytes(in World baseline)
        {
            var writer = GesBitWriter.Counting();
            __WriteDelta(baseline, ref writer, __paths, 0, true);
            writer.Finish();
            var buffer = new byte[writer.RequiredByteCount];
            var count = WriteDelta(baseline, buffer);
            return count == buffer.Length ? buffer : buffer.AsSpan(0, count).ToArray();
        }

        /// <summary>Reads a delta against a baseline into this instance. After an error its values are unspecified.</summary>
        /// <param name="data">The delta; it may continue after it.</param>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <param name="byteLimit">An optional limit on the bytes of this delta.</param>
        /// <returns>The number of bytes the delta occupies.</returns>
        /// <exception cref="GesWireException">The data is no valid delta for this baseline.</exception>
        public int ReadDelta(ReadOnlySpan<byte> data, in World baseline, long byteLimit = long.MaxValue)
        {
            var reader = new GesBitReader(data, byteLimit);
            __ReadDelta(baseline, ref reader, __paths, 0, true);
            return reader.Finish();
        }

        internal readonly bool __WriteDelta(in World baseline, ref GesBitWriter writer, string[] paths, int at, bool top)
        {
            var first = writer.BitPosition;
            for (var left = 2; left > 0; left -= 64) writer.Write(0, global::System.Math.Min(left, 64));
            var changed = false;
            var ordinal = 0;
            {
                var set0 = false;
                {
                    var value0 = __Wire0(Tick, paths, at);
                    var held0 = __Wire0(baseline.Tick, paths, at);
                    if (value0 != held0)
                    {
                        writer.Write(value0, 16);
                        set0 = true;
                    }
                }
                if (set0)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            {
                var set1 = false;
                {
                    var value1 = __Wire1(X, paths, at);
                    var held1 = __Wire1(baseline.X, paths, at);
                    if (value1 != held1)
                    {
                        writer.Write(value1, 11);
                        set1 = true;
                    }
                }
                if (set1)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            return changed;
        }

        internal bool __ReadDelta(in World baseline, ref GesBitReader reader, string[] paths, int at, bool top)
        {
            var fieldCount = 2;
            reader.Require(fieldCount, at == 0 ? "" : paths[at - 1]);
            var changeBits = reader.BitPosition;
            reader.Seek(changeBits + fieldCount);
            var changed = false;
            var ordinal = 0;
            {
                var payload0 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set0 = reader.Read(1, paths[at + 0]) == 1;
                reader.Seek(payload0);
                if (set0)
                {
                    {
                        var held0 = __Wire0(baseline.Tick, paths, at);
                        var value0 = __Read0(ref reader, paths, at);
                        if (value0 == held0) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 0]);
                        Tick = __Value0(value0);
                    }
                    changed = true;
                }
                else
                {
                    Tick = baseline.Tick;
                }
                ordinal++;
            }
            {
                var payload1 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set1 = reader.Read(1, paths[at + 1]) == 1;
                reader.Seek(payload1);
                if (set1)
                {
                    {
                        var held1 = __Wire1(baseline.X, paths, at);
                        var value1 = __Read1(ref reader, paths, at);
                        if (value1 == held1) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 1]);
                        X = __Value1(value1);
                    }
                    changed = true;
                }
                else
                {
                    X = baseline.X;
                }
                ordinal++;
            }
            return changed;
        }
    }

    /// <summary>The network <c>:Game</c>: its hash, the index of each route, the rate of each topic that has one and a typed function per route.</summary>
    internal static class Game
    {
        /// <summary>The network hash over the routes and their bound roots, which the handshake compares.</summary>
        public const ulong Hash = 0xf589a3e2e3aaff61UL;

        /// <summary>The index of the route <c>client sends :Commands reliable</c>.</summary>
        public const int ClientSendsCommands = 0;

        /// <summary>The index of the route <c>server publishes :World latest</c>.</summary>
        public const int ServerPublishesWorld = 1;

        /// <summary>The shortest interval between two updates of the topic <c>:World</c> in microseconds.</summary>
        public const long ServerPublishesWorldEveryMicroseconds = 50000;

        /// <summary>The index of the route <c>server sends :Chunk bulk</c>.</summary>
        public const int ServerSendsChunk = 2;

        /// <summary>Encodes <paramref name="value"/> into <paramref name="buffer"/> and sends it on the route <c>client sends :Commands reliable</c>.</summary>
        /// <param name="connection">The client's connection.</param>
        /// <param name="value">The record.</param>
        /// <param name="buffer">The buffer the record is encoded into; its <c>MaxByteCount</c> bytes always suffice.</param>
        /// <returns>The status of <see cref="GesNetworkConnection.Send(int, ReadOnlySpan{byte})"/>.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, or the buffer is too small.</exception>
        public static GesNetworkSendStatus ClientSendCommands(GesNetworkConnection connection, in global::GameEventScript.Tests.Generator.Network.Wire.Commands value, Span<byte> buffer)
            => connection.Send(ClientSendsCommands, buffer.Slice(0, value.Write(buffer)));

        /// <summary>Encodes <paramref name="value"/> into <paramref name="buffer"/> and publishes it on the route <c>server publishes :World latest</c>.</summary>
        /// <param name="connection">The server's connection.</param>
        /// <param name="value">The record.</param>
        /// <param name="buffer">The buffer the record is encoded into; its <c>MaxByteCount</c> bytes always suffice.</param>
        /// <returns>The status of <see cref="GesNetworkConnection.Publish(int, ReadOnlySpan{byte})"/>.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, or the buffer is too small.</exception>
        public static GesNetworkSendStatus ServerPublishWorld(GesNetworkConnection connection, in global::GameEventScript.Tests.Generator.Network.Wire.World value, Span<byte> buffer)
            => connection.Publish(ServerPublishesWorld, buffer.Slice(0, value.Write(buffer)));

        /// <summary>Encodes <paramref name="value"/> into <paramref name="buffer"/> and sends it on the route <c>server sends :Chunk bulk</c>.</summary>
        /// <param name="connection">The server's connection.</param>
        /// <param name="value">The record.</param>
        /// <param name="buffer">The buffer the record is encoded into; its <c>MaxByteCount</c> bytes always suffice.</param>
        /// <returns>The status of <see cref="GesNetworkConnection.Send(int, ReadOnlySpan{byte})"/>.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, or the buffer is too small.</exception>
        public static GesNetworkSendStatus ServerSendChunk(GesNetworkConnection connection, in global::GameEventScript.Tests.Generator.Network.Wire.Chunk value, Span<byte> buffer)
            => connection.Send(ServerSendsChunk, buffer.Slice(0, value.Write(buffer)));
    }
}
